-- Migration 0045_bench_rosters: generated by drizzle-kit (tables, keys, indexes), the extension, the exclusion constraint, RLS, the column-list SET NULL actions and the scope guards hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #384)
-- Effective-dated bench rosters (#384, part 1 of #39; ADR 0017):
--   * bench_roster, bench_roster_entry, bench_change_alert: tenant tables (tenantTable()) under
--     FORCE RLS with ws_isolation (tenantPolicy()). Grants come from the default privileges
--     (app: 02-roles.sql, clerk: 0022).
--   * btree_gist (trusted, created by the database owner) lets bench_roster_active_period_excl mix
--     equality on workspace_id and forum_id with overlap on daterange(effective_from,
--     effective_to, '[)'): no two active rosters of one workspace and forum share a day; a null
--     effective_to is open-ended. Drizzle cannot declare EXCLUDE, so it is absent from the snapshot.
--   * bench_roster.forum_id, bench_roster_entry.hall_id and bench_id, bench_change_alert.old_bench_id
--     and new_bench_id are single-column FKs into the global-or-workspace court tables, guarded by
--     app_reference_scope_guard in mode same_or_global.
--   * bench_roster.imported_by and source_document_id are ON DELETE SET NULL (<column>) (Postgres
--     15+): drizzle-kit writes a plain SET NULL, which would also null the NOT NULL workspace_id;
--     its snapshot keeps `set null`. Entries cascade with their roster; alerts keep the proceeding
--     and roster they cite (NO ACTION).
--   * No column, index or constraint names or covers judges (PX-9, ME-6): an entry names a bench.
-- Expand only: an extension, new tables and triggers.
CREATE EXTENSION IF NOT EXISTS btree_gist;--> statement-breakpoint
CREATE TABLE "bench_change_alert" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"proceeding_id" uuid NOT NULL,
	"roster_id" uuid NOT NULL,
	"old_bench_id" uuid,
	"new_bench_id" uuid NOT NULL,
	"reason" text NOT NULL,
	"status" text DEFAULT 'open' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "bench_change_alert_workspace_id_id_uq" UNIQUE("workspace_id","id"),
	CONSTRAINT "bench_change_alert_proceeding_roster_uq" UNIQUE("proceeding_id","roster_id"),
	CONSTRAINT "bench_change_alert_reason_chk" CHECK (reason in ('hall', 'portfolio')),
	CONSTRAINT "bench_change_alert_status_chk" CHECK (status in ('open', 'dismissed'))
);
--> statement-breakpoint
CREATE TABLE "bench_roster" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"forum_id" uuid NOT NULL,
	"effective_from" date NOT NULL,
	"effective_to" date,
	"status" text DEFAULT 'draft' NOT NULL,
	"version" integer NOT NULL,
	"source_document_id" uuid,
	"imported_by" uuid,
	"note" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "bench_roster_workspace_id_id_uq" UNIQUE("workspace_id","id"),
	CONSTRAINT "bench_roster_forum_version_uq" UNIQUE("workspace_id","forum_id","version"),
	CONSTRAINT "bench_roster_status_chk" CHECK (status in ('draft', 'active', 'superseded')),
	CONSTRAINT "bench_roster_version_chk" CHECK (version > 0),
	CONSTRAINT "bench_roster_period_chk" CHECK (effective_to is null or effective_to > effective_from)
);
--> statement-breakpoint
CREATE TABLE "bench_roster_entry" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"roster_id" uuid NOT NULL,
	"hall_id" uuid,
	"hall_no" text NOT NULL,
	"bench_id" uuid NOT NULL,
	"portfolio_text" text DEFAULT '' NOT NULL,
	"portfolio_rule" jsonb,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "bench_roster_entry_workspace_id_id_uq" UNIQUE("workspace_id","id"),
	CONSTRAINT "bench_roster_entry_hall_no_chk" CHECK (btrim(hall_no) <> ''),
	CONSTRAINT "bench_roster_entry_portfolio_rule_chk" CHECK (portfolio_rule is null or jsonb_typeof(portfolio_rule) = 'object')
);
--> statement-breakpoint
